Input: {"question": "When was Princess Xenia born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 0, "end": 150, "text": "Princess Xenia Andreevna of Russia Princess Xenia Andreevna Romanoff (10 March 1919 – 22 October 2000) was a direct descendant of the Tsars of Russia."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 151, "end": 223, "text": "She was a great niece of Nicholas II, the last reigning Russian Emperor."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 224, "end": 275, "text": "Princess Xenia was born in Paris, on 10 March 1919."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 276, "end": 412, "text": "She was the eldest child of Prince Andrei Alexandrovich of Russia (24 January 1897 – 8 May 1981) and Donna Elisabetha Ruffo (1886–1940)."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 413, "end": 475, "text": "Xenia Andreevna descended twice over from the Tsars of Russia."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0467-aca95c5edc0c:d00", "start": 476, "end": 601, "text": "Her paternal grandfather, Grand Duke Alexander Mikhailovich, was the fourth son of Grand Duke Michael, himself the fourth son"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0467-aca95c5edc0c:d01", "start": 0, "end": 189, "text": "Prince Andrei Alexandrovich of Russia Mother Elisabetha di Sasso Ruffo Princess Xenia Andreevna Romanoff ( 10 March 1919 – 22 October 2000 ) was a direct descendant of the Tsars of Russia ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0467-aca95c5edc0c:d01", "start": 190, "end": 264, "text": "She was a great niece of Nicholas II , the last reigning Russian Emperor ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0467-aca95c5edc0c:d01", "start": 265, "end": 395, "text": "Biography [ edit ] Princess Xenia was born in Paris , on 10 March 1919 , where her parents had fled after the Russian Revolution ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0467-aca95c5edc0c:d01", "start": 396, "end": 533, "text": "She was the eldest child of Prince Andrei Alexandrovich of Russia ( 24 January 1897 – 8 May 1981 ) and Donna Elisabetha Ruffo ( 1886–1940"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 0, "end": 37, "text": "From Wikipedia, the free encyclopedia"}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 38, "end": 108, "text": "Russian princess and Tsar descendant Princess Xenia Andreevna Romanoff"}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 109, "end": 153, "text": "Born (1922-07-15) 15 July 1922 Paris, France"}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 154, "end": 197, "text": "Died 22 October 2000 (2000-10-22) (aged 78)"}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 198, "end": 234, "text": "Spouse Calhoun Ancrum Geoffrey Tooth"}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 235, "end": 265, "text": "House Holstein-Gottorp-Romanov"}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 266, "end": 316, "text": "Father Grand Duke Alexander Mikhailovich of Russia"}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 318, "end": 436, "text": "Princess Xenia Andreevna Romanoff, a member of the Russian imperial family, was born on 15 July 1922 in Paris, France."}, "D3S9": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 437, "end": 578, "text": "She spent her early years in exile following the Russian Revolution, which forced many members of the Romanov dynasty to flee their homeland."}, "D3S10": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 579, "end": 707, "text": "Princess Xenia married Calhoun Ancrum Geoffrey Tooth and was a prominent figure in the expatriate community throughout her life."}, "D3S11": {"document_number": 3, "doc_id": "ramdocs-0467-aca95c5edc0c:d02", "start": 708, "end": 760, "text": "She passed away on 22 October 2000 at the age of 78."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 0, "end": 265, "text": "Princess Xenia Georgievna of Russia Princess Xenia Georgievna of Russia (22 August 1903, Mikhailovskoe, Russia – 17 September 1965, Glen Cove, New York) was the daughter of Grand Duke George Mihailovich of Russia and Princess Maria Georgievna of Greece and Denmark."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 266, "end": 326, "text": "Her older sister was Princess Nina Georgievna, born in 1901."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 327, "end": 418, "text": "She and her sister left Russia in 1914 to spend the war years in England with their mother."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 419, "end": 584, "text": "In 1919, her father, his brother, Grand Duke Nicholas Mikhailovich, and their cousin, Grand Duke Paul Alexandrovich, were executed by a Bolshevik firing squad in St."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 585, "end": 596, "text": "Petersburg."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0467-aca95c5edc0c:d03", "start": 597, "end": 613, "text": "In the summer of"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0467-aca95c5edc0c:d04", "start": 0, "end": 238, "text": "Princess Xenia of Montenegro Xenia Petrovic-Njegoš, Princess of Montenegro, also known as Princess Ksenija or Kseniya, (22 April 1881 – 10 March 1960) was a member of the House of Petrović-Njegoš as a daughter of Nicholas I of Montenegro."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0467-aca95c5edc0c:d04", "start": 239, "end": 415, "text": "As a young woman, Princess Xenia's appearance in contemporary newspapers was almost entirely the result of seemingly never-ending rumors of suitors, engagements, and marriages."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0467-aca95c5edc0c:d04", "start": 416, "end": 612, "text": "Speculated candidates included but were not limited to Alexander I of Serbia; Greek brothers Prince Nicholas, Prince George, and Prince Andrew; and Ernest Louis, Grand Duke of Hesse, among others."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0467-aca95c5edc0c:d04", "start": 613, "end": 653, "text": "Princess Xenia of Montenegro was born in"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0467-aca95c5edc0c:d05", "start": 0, "end": 327, "text": "Court Church , Cetinje Names Ksenija Petrović-Njegoš House Petrović-Njegoš Father Nicholas I of Montenegro Mother Milena Vukotić Signature Close As a young woman , Princess Xenia 's appearance in contemporary newspapers was almost entirely the result of seemingly never-ending rumours of suitors , engagements , and marriages ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0467-aca95c5edc0c:d05", "start": 328, "end": 531, "text": "Speculated candidates included but were not limited to Alexander I of Serbia ; Greek brothers Prince Nicholas , Prince George , and Prince Andrew ; and Ernest Louis , Grand Duke of Hesse , among others ."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0467-aca95c5edc0c:d05", "start": 532, "end": 611, "text": "Early life Princess Xenia of Montenegro was born in Cetinje on 22 April 1881 as"}}, "original_cards": [{"doc_id": "ramdocs-0467-aca95c5edc0c:d00", "card_id": "ramdocs-0467-aca95c5edc0c:d00:c0", "entity": "Princess Xenia", "scope": "birth date", "claim": "Princess Xenia was born on 10 March 1919.", "answer": "10 March 1919", "quote": "Princess Xenia was born in Paris, on 10 March 1919.", "original_document_number": 1}, {"doc_i